@namespace sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="@(ActiveSection == section.Key ? "active" : "")">
                <button @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span class="section-icon">@section.Icon</span>
                    <span class="section-label">@section.Label</span>
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

.settings-sidebar {
    width: 240px;
    min-height: 100%;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-nav li button {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.75rem 1.5rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    transition: background 0.15s, color 0.15s;
}

.sidebar-nav li button:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-nav li.active button {
    background: #e3f2fd;
    color: #1976d2;
    font-weight: 600;
    border-left: 3px solid #1976d2;
}

.section-icon {
    font-size: 1.1rem;
}

