arguments.file_text:
@namespace sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings
@using sv_b8a95899f5b84ca48db67f447d374096.Models
@using sv_b8a95899f5b84ca48db67f447d374096.Services
@inject ISettingsService SettingsService

<div class="profile-section">
    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-area">
            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(displayName))
                {
                    <img src="@avatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">👤</div>
                }
            </div>
            <span class="avatar-url-label">Avatar URL: @avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="displayName" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="email" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="bio" @bind:event="oninput" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (showSuccessMessage)
        {
            <div class="toast success">Profile saved successfully!</div>
        }
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";

    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccessMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
        avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        isSaving = false;
        showSuccessMessage = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
    }
}

.profile-section {
    max-width: 600px;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url-label {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 600;
    font-size: 0.9rem;
    color: #333;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.loading {
    color: #666;
    font-style: italic;
}

@@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

@namespace sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings
@using sv_b8a95899f5b84ca48db67f447d374096.Models
@using sv_b8a95899f5b84ca48db67f447d374096.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <h4>Notification Channels</h4>

        <div class="toggle-group">
            <label class="toggle-item">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-switch"></span>
            </label>

            <label class="toggle-item">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-switch"></span>
            </label>

            <label class="toggle-item">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-switch"></span>
            </label>
        </div>

        <h4>Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Preferences saved!</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    // Representative channels for the UI
    private static readonly string[] allChannels = ["general", "announcements", "updates", "marketing", "engineering", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

