@namespace sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings
@using sv_b8a95899f5b84ca48db67f447d374096.Models
@using sv_b8a95899f5b84ca48db67f447d374096.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <h4>Notification Channels</h4>

        <div class="toggle-group">
            <label class="toggle-item">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="emailNotifications" />
                <span class="toggle-switch"></span>
            </label>

            <label class="toggle-item">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="pushNotifications" />
                <span class="toggle-switch"></span>
            </label>

            <label class="toggle-item">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="weeklyDigest" />
                <span class="toggle-switch"></span>
            </label>
        </div>

        <h4>Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Preferences saved!</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    // Representative channels for the UI
    private static readonly string[] allChannels = ["general", "announcements", "updates", "marketing", "engineering", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

