{"file_text": "@namespace sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings
@using sv_b8a95899f5b84ca48db67f447d374096.Models
@using sv_b8a95899f5b84ca48db67f447d374096.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="setting-group">
            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var option in themeOptions)
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@option"
                               checked="@(theme == option)"
                               @onchange="() => theme = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="setting-group">
            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var option in fontSizeOptions)
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@option"
                               checked="@(fontSize == option)"
                               @onchange="() => fontSize = option" />
                        <span>@option</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="setting-group">
            <h4>Language</h4>
            <select @bind="language">
                @foreach (var lang in languageOptions)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="setting-group">
            <label class="toggle-item">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="compactMode" />
            </label>
        </div>

        <!-- Live Preview -->
        <div class="setting-group">
            <h4>Preview</h4>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private static readonly string[] themeOptions = ["Light", "Dark", "System"];
    private static readonly string[] fontSizeOptions = ["Small", "Medium", "Large"];
    private static readonly string[] languageOptions = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{theme.ToLowerInvariant()} font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
