toolArgs.file_text:
.security-section {
    max-width: 700px;
}

.panel {
    margin-bottom: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
}

.panel h4 {
    padding: 1rem;
    margin: 0;
    background: #f8f9fa;
    border-bottom: 1px solid #e0e0e0;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 1rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #666;
}

.panel-body {
    padding: 1rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 600;
    font-size: 0.9rem;
    color: #333;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.twofa-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem;
}

.status-badge {
    display: inline-block;
    margin-left: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-badge.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-badge.disabled {
    background: #fbe9e7;
    color: #c62828;
}

.meta-info {
    padding: 0 1rem 1rem;
    font-size: 0.85rem;
    color: #666;
    margin: 0;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem 1rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #fafafa;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.8rem;
    color: #1976d2;
    font-weight: 600;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-danger {
    background: #e53935;
    color: white;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.error-message {
    color: #c62828;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* Confirmation dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin: 0 0 0.75rem;
    background: none;
    border: none;
    padding: 0;
}

.dialog p {
    margin: 0 0 1.25rem;
    color: #555;
    font-size: 0.9rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.loading {
    color: #666;
    font-style: italic;
}

