.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h4 {
    margin-bottom: 0.75rem;
    color: #333;
    font-size: 0.95rem;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-item input[type="radio"] {
    accent-color: #1976d2;
}

select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 6px;
    cursor: pointer;
    max-width: 300px;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Live Preview Area */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.2s ease;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-area.theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    line-height: 1.5;
}

.preview-button {
    padding: 0.4rem 1rem;
    border: none;
    border-radius: 4px;
    background: #1976d2;
    color: white;
    cursor: pointer;
    font-size: 0.9em;
}

.preview-area.theme-dark .preview-button {
    background: #64b5f6;
    color: #1e1e1e;
}

.form-actions {
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.loading {
    color: #666;
    font-style: italic;
}

