arguments.file_text:
@page "/settings"
@using sv_b8a95899f5b84ca48db67f447d374096.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        <h2>@GetSectionTitle()</h2>

        @switch (activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "profile";

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }

    private string GetSectionTitle() => activeSection switch
    {
        "profile" => "Profile",
        "notifications" => "Notifications",
        "security" => "Security",
        "appearance" => "Appearance",
        _ => "Settings"
    };
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 60px);
    background: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #222;
    font-size: 1.5rem;
}

